#!/bin/bash
# Task 092 -- meshsim cc-cores verification for the merge (WORKER14): branch cc-cores at ba34cbf (C&C 1-3 as real cores
# behind Config.ccCores, off by default; main 9133397 merged: s8's 256-byte ROM and two-report dump, s9).
#  1. run_tests.sh's quick suite (tools/run_quick.sh, 8 at a time): every existing suite with the switch off, plus
#     CcCoresTest (the controllers' boot, phases, both error-report sets, the watchdog) and RecipeTest's cc1 driver
#     (rcp_cc1.c run on C&C 1 as a core);
#  2. the full-size sort p4/uniform-k128 (task 089's sortrunner; jar rebuilt from cc-cores at --release 17, HASHES
#     updated; sort image, boot ROM and hops.txt byte-identical to 089's), compared against 1,229,008 cycles.
# The kit (cc-cores/: meshsim at Java 17 with every image prebuilt, sw, tables, tools/replayer-opcodes; sortrunner/) is
# embedded below, SHA-256 checked; smoke-tested locally (run_quick on recipes, cccores, regdoc, replayer; run_p4 at
# n = 2,000: 242,445 cycles, as 089's smoke). Expected ~15 min.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/092-w14-cc-cores-merge; mkdir -p "$RES"
WANT=0f961b227f2f38750ef3ee85b66d88cde60019ca9c0a6d4bcd09b18dfa08dfc4
W=/tmp/w14-092; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/cc-cores/meshsim" || exit 2
P=8 bash tools/run_quick.sh "$W/out"; RQ=$?
cd "$W/sortrunner" || exit 2
printf 'p4/uniform-k128\n' > "$W/p4list"
bash ./run_p4.sh -j 1 -m 6g -l "$W/p4list" "$W/p4"; RS=$?
echo "run_quick.sh exit $RQ, run_p4.sh exit $RS at $(date -u)"
grep -h "TOTAL" "$W"/p4/VERDICT.txt 2>/dev/null | sed 's/^/p4 (main: 1,229,008 cycles): /'
mkdir -p "$RES/p4"; cp "$W"/out/* "$RES/" 2>/dev/null; cp "$W"/p4/* "$RES/p4/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/p4/VERDICT.txt" 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RS = 0 ]; exit $?
